const artStoreObserve = `-- name: ArtStoreObserve :exec
UPDATE store SET
 state=CASE WHEN NOT $1::boolean THEN 'unreachable' WHEN free_space_warning_bytes IS NOT NULL AND coalesce($2::bigint,capacity_bytes) < free_space_warning_bytes THEN 'full' ELSE 'reachable' END,
 capacity_bytes=coalesce($2::bigint,capacity_bytes),
 used_bytes=coalesce($3::bigint,used_bytes),
 observed_at=CASE WHEN $1::boolean THEN now() ELSE observed_at END
WHERE id= $4 AND host_id= $5 AND (
 state IS DISTINCT FROM CASE WHEN NOT $1::boolean THEN 'unreachable' WHEN free_space_warning_bytes IS NOT NULL AND coalesce($2::bigint,capacity_bytes) < free_space_warning_bytes THEN 'full' ELSE 'reachable' END
 OR capacity_bytes IS DISTINCT FROM coalesce($2::bigint,capacity_bytes)
 OR used_bytes IS DISTINCT FROM coalesce($3::bigint,used_bytes)
 OR ($1::boolean AND (observed_at IS NULL OR observed_at < now() - interval '30 seconds')))
`

type ArtStoreObserveParams struct {
	Reachable bool
	Capacity  *int64
	Used      *int64
	ID        string
	HostID    string
}

// The report of a host of one store: full when the capacity left falls below its warning; nothing written when nothing
// changed (observed_at only every 30 seconds).
func (q *Queries) ArtStoreObserve(ctx context.Context, arg ArtStoreObserveParams) error {
	_, err := q.db.Exec(ctx, artStoreObserve,
		arg.Reachable,
		arg.Capacity,
		arg.Used,
		arg.ID,
		arg.HostID,
	)
	return err
}

